// Probe driver for switch-over-distance.md: run the compile path's phases over one
// component of the interpreter's library, with the interpreter's prelude in scope
// (FortressLibrary / FortressBuiltin / AnyType), under either desugaring setting.
//
// Built only from public Shell entry points, as the checker-count stage's WorldFlip.java
// and desugar-codegen/PhaseProbe.java are; no tracked file is modified.  The switches
// that make the checker run every stage and every declaration are -D properties read by
// the shadow classes of make-shadows.sh (probe.tolerant, probe.all, probe.skipOverloads).
//
// Usage: java -cp <shadow-classes>:<classes>:<fortress classpath> Distance
//             [-order check|full] [-setting walk|compile] [-compilerlib] <file.fss|.fsi>
//   -order check    the compiler's own order truncated after TYPECHECK
//                   (PREDISAMBIGUATEDESUGAR .. INTEGERLITERALFOLDING, TYPECHECK);
//                   the checker-count stage runs the whole compilerPhaseOrder, whose
//                   checker results are the same since TYPECHECK throws first
//   -order full     PhaseOrder.compilerPhaseOrder, through CODEGEN
//   -setting walk   Shell.useInterpreterLibraries() as it is: extends-Object
//                   pre-desugaring off, compiled-expression desugaring off
//                   (Shell.java:379-386) -- the setting the checker-count stage runs
//   -setting compile  the same prelude, with the two switches the compile path has
//                   put back: extends-Object pre-desugaring on (Shell.useCompilerLibraries,
//                   Shell.java:371-377) and compiled-expression desugaring on (its
//                   default, Shell.java:1285, which useInterpreterLibraries turns off)
//   -compilerlib    the compiler's own prelude instead (control)
import com.sun.fortress.Shell;
import com.sun.fortress.compiler.phases.PhaseOrder;
import edu.rice.cs.plt.tuple.Option;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Distance {
    public static void main(String[] args) throws Throwable {
        List<String> a = new ArrayList<String>(Arrays.asList(args));
        String order = "check", setting = "walk";
        boolean compilerWorld = false;
        while (!a.isEmpty() && a.get(0).startsWith("-")) {
            String f = a.remove(0);
            if (f.equals("-order")) order = a.remove(0);
            else if (f.equals("-setting")) setting = a.remove(0);
            else if (f.equals("-compilerlib")) compilerWorld = true;
            else throw new RuntimeException("unknown flag " + f);
        }
        PhaseOrder[] ord;
        if (order.equals("full")) ord = PhaseOrder.compilerPhaseOrder;
        else if (order.equals("check")) ord = new PhaseOrder[] {
                PhaseOrder.PREDISAMBIGUATEDESUGAR, PhaseOrder.DISAMBIGUATE, PhaseOrder.GRAMMAR,
                PhaseOrder.PRETYPECHECKDESUGAR, PhaseOrder.INTEGERLITERALFOLDING, PhaseOrder.TYPECHECK };
        else throw new RuntimeException("unknown -order " + order);
        if (!setting.equals("walk") && !setting.equals("compile"))
            throw new RuntimeException("unknown -setting " + setting);

        if (compilerWorld) Shell.useCompilerLibraries();
        else Shell.useInterpreterLibraries();
        if (setting.equals("compile")) {
            Shell.setExtendsObjectPreDesugaring(true);
            Shell.setCompiledExprDesugaring(true);
        } else {
            Shell.setExtendsObjectPreDesugaring(false);
            Shell.setCompiledExprDesugaring(false);
        }
        Shell.setTypeChecking(true);
        Shell.setScala(true);
        Shell.setPhaseOrder(ord);
        StringBuilder sb = new StringBuilder();
        for (PhaseOrder p : ord) sb.append(p.name()).append(' ');
        System.out.println("### order=" + order + " phases=[ " + sb + "] setting=" + setting
                           + " (extendsObject=" + Shell.getExtendsObjectPreDesugaring()
                           + " compiledExpr=" + Shell.getCompiledExprDesugaring() + ")"
                           + " prelude=" + (compilerWorld ? "COMPILER" : "INTERPRETER")
                           + " target=" + a
                           + " overloadCache=" + System.getProperty("fortress.analyzer.overload.cache", "default(true)"));
        int rc = Shell.compilerPhases(a, Option.<String>none(), "compile");
        System.out.println("### rc=" + rc);
        System.exit(rc);
    }
}
#!/usr/bin/env python3
"""errors.py <tsv-out> <run.out>... : every distinct error the checker printed in a set of
runs, one row each, classified by kind.

Reads the `@@SC ERR` lines of add-patch.py (one per error per stage per compilation unit)
and the crash lines (`@@SC CRASH`, and `@@TC DECL-CRASH` of desugar-codegen's per-declaration
check).  An error is identified by its location and its message with paths cut to the file
name; the same error printed by two units, by both well-formedness passes, or by two runs
(each run re-checks the twelve prelude apis) is counted once, as the gate's own total
counts a set.  Writes one row per distinct error to <tsv-out>:
    kind <tab> family <tab> unit(s) <tab> stage <tab> location <tab> message
and prints the tallies.

Kinds:
  exclusion     "X excludes Y but it extends Y", "Types X and Y exclude each other"
  comprises     "Invalid comprises clause"
  overloading   "Invalid overloading of F", "multiple declarations of F with the same
                parameter type"; family F
  return-type   "For F, the return type of ... should be a subtype of ..."; family F
  bound-Object  "... does not satisfy the corresponding bound Object"
  abstract-method  "The inherited abstract method F ... has no concrete implementation"
  typecheck     any other error the component's declarations produced, by message shape
  wellformed    any other error of the two well-formedness passes ("Ill-formed type ...")
  export        the export checker: a component that does not match its api
  other/<stage> anything else"""
import collections, re, sys

LOC = re.compile(r"(/\S+?/)?([\w.]+\.fs[si]):(\d+):\d+(?:-\d+)?(?::\d+)?")
PREFIX = re.compile(r"^((?:\S+?\.fs[si]:\d+:\d+(?:-\d+)?(?::\d+)?:\s*)+)(.*)$")

def norm(s):
    s = re.sub(r"/\S*?/([\w.]+\.fs[si])", r"\1", s)
    s = re.sub(r"\$\d+", "", s)                      # fresh inference-variable numbers
    return re.sub(r"\s+", " ", s).strip()

def shape(msg):
    """a message with its names and types cut out, for grouping the rest"""
    m = re.sub(r"\[\\.*\\\]", "[\\..\\]", msg)
    m = re.sub(r"\b[\w.]+\.fs[si]:\d+(:\d+(-\d+)?)?", "L", m)
    m = re.sub(r"`[^`]*`|'[^']*'|\"[^\"]*\"", "Q", m)
    return m[:110]

def sparams(sig):
    """the static parameters of a signature `[\\...\\](...)->...`, names replaced by position
    (triage/classify.py's test), or None when it has none"""
    sig = sig.strip()
    if not sig.startswith("[\\"): return None
    i, depth, body = 2, 1, ""
    while depth and i < len(sig):
        if sig.startswith("[\\", i): depth += 1; body += "[\\"; i += 2; continue
        if sig.startswith("\\]", i):
            depth -= 1
            if depth: body += "\\]"
            i += 2; continue
        body += sig[i]; i += 1
    ps, depth, cur = [], 0, ""
    for ch in body:
        if ch == "," and depth == 0: ps.append(cur.strip()); cur = ""; continue
        depth += ch == "["; depth -= ch == "]"; cur += ch
    ps.append(cur.strip())
    names = [p.split(" extends ")[0].replace("nat ", "").replace("int ", "").strip() for p in ps]
    out = []
    for p in ps:
        b = p.split(" extends ")[1] if " extends " in p else ""
        for j, n in enumerate(names): b = re.sub(r"\b%s\b" % re.escape(n), "#%d" % j, b)
        out.append(("nat" if p.startswith("nat ") else "type", b))
    return out

def params(sig):
    """the parameter list of a signature, the text inside its first top-level parentheses"""
    s = sig.strip()
    if s.startswith("[\\"):
        d, i = 1, 2
        while d and i < len(s):
            if s.startswith("[\\", i): d += 1; i += 2; continue
            if s.startswith("\\]", i): d -= 1; i += 2; continue
            i += 1
        s = s[i:]
    if not s.startswith("("): return s.split("->")[0]
    d = 0
    for i, ch in enumerate(s):
        d += ch == "("; d -= ch == ")"
        if d == 0: return s[1:i]
    return s

def overload_sub(name, msg):
    """fill-crossed: a function-taking fill against a value-taking one (triage's e1);
    fill-same: two of one kind, from the two sides of the array traits' diamond;
    sentence: the two declarations' static parameters differ, the case of
    Specification/basic/overloading.tex:100-107 (triage's b);
    same-sparams: neither -- no Subtype Rule, no exclusion, no declaration on the meet"""
    r = re.search(r"Invalid overloading of \S+ in (.*?): (.*?) and (.*)$", msg)
    if not r: return "same parameter type" if "same parameter type" in msg else "?"
    a, b = r.group(2), r.group(3)
    if name == "fill":
        fa, fb = "->" in params(a), "->" in params(b)
        return "fill-crossed" if fa != fb else "fill-same"
    sa, sb = sparams(a), sparams(b)
    if (sa is None) != (sb is None) or (sa is not None and sa != sb): return "sentence"
    return "same-sparams"

def classify(stage, msg):
    if re.search(r"excludes .* but it extends", msg) or re.search(r"exclude each other", msg):
        return "exclusion", "-"
    if "comprises" in msg and ("Invalid comprises" in msg or "comprises clause" in msg):
        return "comprises", "-"
    r = re.search(r"Invalid overloading of (\S+) in", msg)
    if r: return "overloading", r.group(1)
    r = re.search(r"multiple declarations of (\S+) with the same parameter type", msg)
    if r: return "overloading", r.group(1) + " (same parameter type)"
    r = re.search(r"For (\S+), the return type of", msg)
    if r: return "return-type", r.group(1)
    if "corresponding bound Object" in msg or re.search(r"bound Object\b", msg):
        return "bound-Object", "-"
    r = re.search(r"inherited abstract method (?:abstract getter )?(\S+?)[(:\[].*has no concrete implementation", msg)
    if r: return "abstract-method", r.group(1)
    if stage == "typecheck": return "typecheck", shape(msg)
    if stage.startswith("wellformed"): return "wellformed", shape(msg)
    if stage == "export": return "export", shape(msg)
    return "other/" + stage, shape(msg)

out_path, runs = sys.argv[1], sys.argv[2:]
seen = collections.OrderedDict()
crashes = collections.OrderedDict()
stage_raw = collections.Counter()
for path in runs:
    for raw in open(path, encoding="utf-8", errors="replace"):
        f = raw.rstrip("\n").split("\t")
        if f[0] == "@@SC ERR" and len(f) >= 4:
            unit, stage, text = f[1], f[2], "\t".join(f[3:])
            stage_raw[(unit, stage)] += 1
            m = PREFIX.match(text.strip())
            locs, msg = (m.group(1), m.group(2)) if m else ("", text)
            loc = ",".join(sorted(set("%s:%s" % (g[1], g[2]) for g in LOC.findall(locs)))) or "?"
            msg = norm(msg)
            key = (loc, msg)
            if key not in seen: seen[key] = [set(), set()]
            seen[key][0].add(unit); seen[key][1].add(stage)
        elif f[0] == "@@SC CRASH":
            k = (f[1], f[2], f[3], f[4] if len(f) > 4 else "")
            crashes[("stage",) + k] = crashes.get(("stage",) + k, 0) + 1
        elif f[0] == "@@TC DECL-CRASH":
            k = (norm(f[2]), f[3], f[4] if len(f) > 4 else "")
            crashes[("decl",) + k] = crashes.get(("decl",) + k, 0) + 1

rows = []
for (loc, msg), (units, stages) in seen.items():
    st = sorted(stages)[0] if len(stages) == 1 else "+".join(sorted(stages))
    kind, fam = classify(sorted(stages)[-1], msg)
    sub = overload_sub(fam.split(" ")[0], msg) if kind == "overloading" else "-"
    rows.append((kind, fam, sub, "+".join(sorted(units)), st, loc, msg))
rows.sort()
with open(out_path, "w", encoding="utf-8") as o:
    o.write("# kind\tfamily\tsubclass\tunit(s)\tstage(s)\tlocation\tmessage\n")
    for r in rows: o.write("\t".join(r) + "\n")
rows = [(r[0], r[1], r[3], r[4], r[5], r[6], r[2]) for r in rows]   # subclass last, below

print("# %d distinct errors from %d runs; %d raw error lines" % (len(rows), len(runs), sum(stage_raw.values())))
kinds = collections.Counter(r[0] for r in rows)
print("\n## by kind")
for k, n in kinds.most_common(): print("%6d  %s" % (n, k))
print("\n## overloading and return-type errors by family")
fam = collections.Counter((r[0], r[1]) for r in rows if r[0] in ("overloading", "return-type"))
for (k, f), n in sorted(fam.items(), key=lambda kv: (kv[0][0], -kv[1], kv[0][1])): print("%6d  %-12s %s" % (n, k, f))
print("\n## overloading errors by subclass (overload_sub)")
sc = collections.Counter(r[6] for r in rows if r[0] == "overloading")
for k, n in sc.most_common(): print("%6d  %s" % (n, k))
print("\n## overloading errors by family and subclass")
fs = collections.Counter((r[1], r[6]) for r in rows if r[0] == "overloading")
for (f, s), n in sorted(fs.items(), key=lambda kv: (-kv[1], kv[0])): print("%6d  %-40s %s" % (n, f, s))
print("\n## the rest by message shape")
rest = collections.Counter((r[0], r[1]) for r in rows if r[0] not in ("overloading", "return-type", "exclusion", "comprises", "bound-Object", "abstract-method"))
for (k, f), n in rest.most_common(): print("%6d  %-14s %s" % (n, k, f))
print("\n## distinct errors by unit and stage (an error printed by several units is under each)")
us = collections.Counter()
for r in rows:
    for u in r[2].split("+"): us[(u, r[3])] += 1
for (u, s), n in sorted(us.items()): print("%6d  %-32s %s" % (n, u, s))
KS = ["exclusion", "comprises", "overloading", "return-type", "abstract-method", "bound-Object",
      "wellformed", "typecheck", "export", "other"]
def big(k):
    return k if k in KS else "other"
print("\n## distinct errors, kind by unit (an error printed by several units is under the first)")
mat = collections.defaultdict(collections.Counter)
for r in rows: mat[r[2].split("+")[0]][big(r[0])] += 1
print("%-26s %s %6s" % ("unit", " ".join("%6s" % k[:6] for k in KS), "total"))
for u in sorted(mat):
    print("%-26s %s %6d" % (u, " ".join("%6d" % mat[u][k] for k in KS), sum(mat[u].values())))
tot = collections.Counter()
for u in mat: tot.update(mat[u])
print("%-26s %s %6d" % ("all", " ".join("%6d" % tot[k] for k in KS), sum(tot.values())))
print("\n## crashes (stage crashes caught by add-patch.py; declarations the checker crashed on)")
for k, n in crashes.items(): print("%6d  %s" % (n, "\t".join(k)[:300]))

"""Edits made on top of desugar-codegen's shadow StaticChecker.java, in place.

usage: add-patch.py <shadow-src>

<shadow-src> holds the shadow sources that ../desugar-codegen/shadow-patch.py wrote from
the tracked ones; this script edits the copy of StaticChecker.java there, and writes two
more shadows from the tracked sources (Desugarer, NodeComparator; the end of this file).
Run from $FORTRESS_HOME.  Nothing tracked is modified.  Every edit is inert unless its
-D switch is given (probe.all; probe.tolerant; probe.bottomCompare).

With -Dprobe.all=true (for components only if -Dprobe.componentOnly=true too, so that a
run over a small component does not repeat the apis' long overloading check),
StaticChecker.checkCompilationUnit
  * runs every stage of the check whatever the earlier stages reported: the tracked
    method returns after the hierarchy check, after the api-type extraction, after the
    second well-formedness check and after the overloading check whenever an error
    exists (StaticChecker.java:191-193, :200-201, :269-272, :276-279 on the tree of
    2026-09-26, commit 8f806ba67);
  * catches a crash in any stage, prints it and goes on;
  * prints every error each stage added, one line each:
        @@SC ERR <tab> api|component <name> <tab> <stage> <tab> <the error, on one line>
    and a count per stage:
        @@SC STAGE <tab> api|component <name> <tab> <stage> <tab> errors=<n>
Stages: hierarchy, apiextract (components), acyclic, wellformed1, typecheck
(components), wellformed2, overloading, export (components), variance (components,
compile-path setting only, as in the tracked method).
"""
import io, os, sys

shadow = sys.argv[1]
p = os.path.join(shadow, "com/sun/fortress/compiler/StaticChecker.java")
t = io.open(p, encoding="utf-8").read()

def rep(old, new):
    global t
    assert t.count(old) == 1, ("anchor not unique or missing", old[:70], t.count(old))
    t = t.replace(old, new, 1)

CATCH = "catch (RuntimeException | Error __t) { if (!__all) throw __t; probeCrash(__unit, \"%s\", __t); }"

# helpers
rep("    private static CompilationUnitIndex buildIndex(CompilationUnit ast, boolean isApi) {",
"""    // PROBE (switch-over-distance): -Dprobe.all=true runs every stage, see add-patch.py.
    static final boolean PROBE_ALL = Boolean.getBoolean("probe.all");
    static int probeStage(boolean all, String unit, String stage, List<StaticError> errors, int mark) {
        if (!all) return errors.size();
        System.out.println("@@SC STAGE\\t" + unit + "\\t" + stage + "\\terrors=" + (errors.size() - mark));
        for (int i = mark; i < errors.size(); i++)
            System.out.println("@@SC ERR\\t" + unit + "\\t" + stage + "\\t"
                               + String.valueOf(errors.get(i)).replace('\\n', ' ').replace('\\t', ' '));
        return errors.size();
    }
    static void probeCrash(String unit, String stage, Throwable t) {
        StackTraceElement[] st = t.getStackTrace();
        System.out.println("@@SC CRASH\\t" + unit + "\\t" + stage + "\\t" + t.getClass().getName() + "\\t"
                           + (st.length > 0 ? st[0].toString() : "?") + "\\t"
                           + String.valueOf(t.getMessage()).replace('\\n', ' ').replace('\\t', ' '));
        for (int i = 0; i < Math.min(8, st.length); i++)
            System.out.println("@@SC CRASHAT\\t" + unit + "\\t" + stage + "\\t" + st[i]);
    }

    private static CompilationUnitIndex buildIndex(CompilationUnit ast, boolean isApi) {""")

rep("""            List<StaticError> errors = new ArrayList<StaticError>();

            if (isApi) {""",
"""            List<StaticError> errors = new ArrayList<StaticError>();
            final String __unit = (isApi ? "api " : "component ") + index.ast().getName();
            // -Dprobe.componentOnly: the apis are checked as the tracked method does
            final boolean __all = PROBE_ALL && !(isApi && Boolean.getBoolean("probe.componentOnly"));
            int __mark = 0;

            if (isApi) {""")

# hierarchy
rep("""            errors.addAll(typeHierarchyChecker.checkHierarchy());
            if (! errors.isEmpty()) {
                return new TypeCheckerResult(ast, errors);
            }""",
"""            __mark = errors.size();
            try { errors.addAll(typeHierarchyChecker.checkHierarchy()); } """ + CATCH % "hierarchy" + """
            __mark = probeStage(__all, __unit, "hierarchy", errors, __mark);
            if (! errors.isEmpty() && !__all) {
                return new TypeCheckerResult(ast, errors);
            }""")

# api type extraction (components)
rep("""                ast = (Component)typeExtractor.check();
                errors.addAll(typeExtractor.getErrors());
                if(!errors.isEmpty())
                    return new TypeCheckerResult(ast,errors);""",
"""                try {
                    ast = (Component)typeExtractor.check();
                    errors.addAll(typeExtractor.getErrors());
                } """ + CATCH % "apiextract" + """
                __mark = probeStage(__all, __unit, "apiextract", errors, __mark);
                if(!errors.isEmpty() && !__all)
                    return new TypeCheckerResult(ast,errors);""")

# acyclic hierarchy and first well-formedness check
rep("""            errors.addAll(typeHierarchyChecker.checkAcyclicHierarchy(typeAnalyzer));
            errors.addAll(new TypeWellFormedChecker(index, env, typeAnalyzer).check());""",
"""            try { errors.addAll(typeHierarchyChecker.checkAcyclicHierarchy(typeAnalyzer)); } """ + CATCH % "acyclic" + """
            __mark = probeStage(__all, __unit, "acyclic", errors, __mark);
            try { errors.addAll(new TypeWellFormedChecker(index, env, typeAnalyzer).check()); } """ + CATCH % "wellformed1" + """
            __mark = probeStage(__all, __unit, "wellformed1", errors, __mark);""")

# the thunks, which run over the whole component before the declarations are checked
rep("""                    thunker.walk(component_ast);""",
"""                    try { thunker.walk(component_ast); } """ + CATCH % "thunker")
rep("""                    com.sun.fortress.scala_src.typechecker.Thunker$.MODULE$.primeFunctionals(componentIndex.parametricOperators(), tryChecker, cycleChecker);
                    com.sun.fortress.scala_src.typechecker.Thunker$.MODULE$.primeFunctionals(componentIndex.functions().secondSet(), tryChecker, cycleChecker);""",
"""                    try {
                    com.sun.fortress.scala_src.typechecker.Thunker$.MODULE$.primeFunctionals(componentIndex.parametricOperators(), tryChecker, cycleChecker);
                    com.sun.fortress.scala_src.typechecker.Thunker$.MODULE$.primeFunctionals(componentIndex.functions().secondSet(), tryChecker, cycleChecker);
                    } """ + CATCH % "prime")

# the component's declarations
rep("""                    errors.addAll(Lists.toJavaList(typeChecker.getErrors()));
                    result = new TypeCheckerResult(ast, errors, typeChecker);""",
"""                    errors.addAll(Lists.toJavaList(typeChecker.getErrors()));
                    __mark = probeStage(__all, __unit, "typecheck", errors, __mark);
                    result = new TypeCheckerResult(ast, errors, typeChecker);""")

# the leftover-inference-variable assertion, reached only when there is no error
rep("""            if( errors.isEmpty() && STypesUtil.assertAfterTypeChecking(result.ast()) )
                bug("Result of typechecking still contains intermediate nodes.\\n" +
                    result.ast());""",
"""            try {
            if( errors.isEmpty() && STypesUtil.assertAfterTypeChecking(result.ast()) )
                bug("Result of typechecking still contains intermediate nodes.\\n" +
                    result.ast());
            } """ + CATCH % "leftover")

# second well-formedness check, then the overloading checker
rep("""            errors.addAll(new TypeWellFormedChecker(index, env, typeAnalyzer).check());
            if ( ! errors.isEmpty() ) {
                result = addErrors(errors, result);
                return result;
            }""",
"""            try { errors.addAll(new TypeWellFormedChecker(index, env, typeAnalyzer).check()); } """ + CATCH % "wellformed2" + """
            __mark = probeStage(__all, __unit, "wellformed2", errors, __mark);
            if ( ! errors.isEmpty() && !__all ) {
                result = addErrors(errors, result);
                return result;
            }""")
rep("""            errors.addAll(new OverloadingChecker(index, env).checkOverloading());
            if ( ! errors.isEmpty() ) {
                result = addErrors(errors, result);
                return result;
            }""",
"""            try { errors.addAll(new OverloadingChecker(index, env).checkOverloading()); } """ + CATCH % "overloading" + """
            __mark = probeStage(__all, __unit, "overloading", errors, __mark);
            if ( ! errors.isEmpty() && !__all ) {
                result = addErrors(errors, result);
                return result;
            }""")

# export and variance (components)
rep("""                errors.addAll(ExportChecker.checkExports((ComponentIndex)index, env));
                result = addErrors(errors, result);""",
"""                try { errors.addAll(ExportChecker.checkExports((ComponentIndex)index, env)); } """ + CATCH % "export" + """
                __mark = probeStage(__all, __unit, "export", errors, __mark);
                result = addErrors(errors, result);""")
rep("""                errors.addAll(VarianceChecker.run((Component) result.ast()));""",
"""                try { errors.addAll(VarianceChecker.run((Component) result.ast())); } """ + CATCH % "variance" + """
                __mark = probeStage(__all, __unit, "variance", errors, __mark);""")

io.open(p, "w", encoding="utf-8").write(t)
print("probe.all edits written to " + p)

# ------------------------------------------------------------------------------------
# Two more shadows, copied from the tracked sources (run from $FORTRESS_HOME), for the
# code-generation run of step `codegen`, which on today's tree does not get past
# DESUGAR and OVERLOADREWRITE as it did on 2026-09-20:
#
#   Desugarer      under -Dprobe.tolerant, a desugaring that throws on the whole
#                  component is applied again one top-level declaration at a time; a
#                  declaration it throws on is printed (@@DS FAIL) and kept undesugared.
#   NodeComparator under -Dprobe.bottomCompare, two BottomTypes compare equal instead of
#                  throwing "subtypeCompareTo(BottomType BottomType) is not implemented!"
#                  (NodeComparator.java:469-471); the first three comparisons print the
#                  stack that reached them (@@NC BOTTOM).
def copy_patch(rel, edits):
    src = os.path.join("ProjectFortress/src/com/sun/fortress", rel)
    s = io.open(src, encoding="utf-8").read()
